const $=selector=>document.querySelector(selector),$$=selector=>[...document.querySelectorAll(selector)],fmt=(value,digits=0)=>Number(value).toLocaleString('en-US',{maximumFractionDigits:digits,minimumFractionDigits:digits});
const state={view:'explore',body:'mars',targetId:'jezero',earthId:'wadi-rum',globeBody:'earth',task:'terrain',terrains:new Map(),stats:new Map(),weights:{slope:.65,relief:.35},rankings:[],evidenceOpen:false,ready:false,observations:[],customSites:[],searchCoverage:null};
try{const saved=JSON.parse(localStorage.getItem('terramatch-observations')||'[]');if(Array.isArray(saved))state.observations=saved.filter(o=>o&&typeof o.siteId==='string'&&Number.isFinite(o.height));}catch{}
