  const detailHTML=detailed?'<p class="detailed-coverage"><strong>Detailed coastline screen: '+(detailed.available?fmt(detailed.land)+' / '+fmt(detailed.total)+' grid points on mapped land; '+fmt(detailed.coastlineIntersections)+' coastline intersections.':'unavailable · score withheld.')+'</strong> '+esc(detailed.method||'Recheck this location when the coastline data can be loaded.')+'</p>':'';
